def _apply(prompt_model, mapping):
    """Update ONLY promptContent, and only for ids that still exist."""
    touched = 0
    for pid, content in mapping.items():
        updated = prompt_model.objects.filter(idPrompt=pid).update(
            promptContent=content)
        touched += updated
    print("--- [i18n] Catalog of Prompts: %d prompt(s) updated" % touched)


def to_spanish(apps, schema_editor):
    _apply(apps.get_model("agent", "Prompt"), SPANISH)


def to_english(apps, schema_editor):
    _apply(apps.get_model("agent", "Prompt"), ENGLISH)


class Migration(migrations.Migration):

    dependencies = [("agent", "0190_add_pdfer_demo_prompts")]

    operations = [migrations.RunPython(to_spanish, to_english)]
